using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Constants.Moments;

internal sealed class CountableHankelNegativeIndexDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Complete-spectrum upper negative index",
        H("Complete-spectrum upper negative index"),
        Blocks(Describe.Lean(
                DescribeId.Create("negative-index-le"),
                DeclarationHandle.Create("D5/S3/Constants/Moments/CountableHankelNegativeIndex.negativeIndex_le"),
                H("An exhaustive active-pair cover bounds every negative polynomial subspace"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every index type iota, complex maps z,w, permutation c, natural r and selector s from Fin r to iota, assume that all node norms are at most one, z(c(i)) is conjugate(z(i)), w(c(i)) is conjugate(w(i)), and the norms of all weights are summable. Coverage means that every i with nonreal z(i) and nonzero w(i) equals s(j) or c(s(j)) for some j. At every real node require the real part of w(i) to be nonnegative. Then the complete negativeIndex, as defined in ExactStickyReduction, of the real-polynomial energy p mapped to the real part of the full sum over i of w(i) p(z(i)) squared is at most r in WithTop Nat. Each square is the ordinary complex square.")),
                    Paragraph(Text("Choose a complex square root b(j) of w(s(j)), including when that weight vanishes. Polynomial evaluation is real linear. Compose its algebra homomorphism's linear map with multiplication on the left by b(j) and the imaginary-part linear map, then take the finite product to obtain L from real polynomials to real vectors on Fin r. Its j-th coordinate is Im(b(j) p(z(s(j)))). The private nonneg_of_readouts_eq_zero is consumed by the upper-bound theorem: on the kernel of L, each representative's summand has real part Re(b(j) p(z(s(j)))) squared and is nonnegative. The local heval_conj and hpair_re prove that the conjugate partner has the same real part because evaluation of a real polynomial commutes with conjugation. They use only the stated node and weight conjugation laws, without an involution premise. At a real node the polynomial value is real, so the real part of the summand is Re(w(i)) times that real value squared. A zero weight gives zero.")),
                    Paragraph(Text("These cases cover every original index individually. The existing square_summable theorem supplies absolute convergence on the unit disk, Complex.re_tsum moves the real part through this convergent sum, and tsum_nonneg proves nonnegativity of the entire form on the constraint kernel. No permutation of the sum, finite head, tail truncation, or replacement by an absolute square is used. The pinned supplier d7b61643dc7c4c0dc660d47282738fb825199bd2 already exposes square_summable at its original CountableHankelNegativeWitness owner. This module imports that theorem and supplies no duplicate proof. The index type may be arbitrary; the summability hypothesis controls the full spectrum without requiring a countable enumeration.")),
                    Paragraph(Text("For each n in the existing negativeRanks set, take its strict negative linear injection T from real vectors on Fin n to real polynomials. A nonzero vector in the kernel of L composed with T would have negative energy by the negativeRanks witness and nonnegative energy by the private kernel argument. The proof explicitly shows that the only vector mapped to zero by L composed with T is zero, and applies LinearMap.ker_eq_bot' and LinearMap.ker_eq_bot to obtain injectivity. LinearMap.finrank_le_finrank_of_injective and Module.finrank_fin_fun give n at most r. Every natural number in the image defining negativeIndex is therefore at most r; sSup_le gives the stated complete-index bound, including the possibility of an infinite negative index in the definition.")),
                    Paragraph(Text("The empty cover r=0 forces every nonreal node to have zero weight. All constraints then vanish for every polynomial because Fin 0 is empty, so the same private argument proves the full form nonnegative for every real polynomial. Zero weights, a zero polynomial, empty spectra, real nodes of zero or negative real location, and vanishing real weight parts remain included. No injectivity of z or s, pair separation, nonzero selected weights, positive-radius finite cuts, or involutivity of c is assumed. Extra or repeated representatives may give redundant constraints and an upper bound larger than the actual index.")),
                    Paragraph(Text("Node boundedness is used for actual summability, not as a finite-spectrum assumption. Summable weights without bounded nodes do not suffice: for natural n, z(n)=2 to power n, w(n)=2 to power minus n and p=X give summands 2 to power n, which are not summable. The stated unit-disk assumption and the original summability theorem avoid the unspecified value of a divergent tsum.")),
                    Paragraph(Text("For the later exact-index application, impose separately the full hypotheses of CountableHankelNegativeWitness.exists_real_negative_family in the staged CountableHankelNegativeFamily module: injective nodes, finite positive-radius cuts, an injective selector of k mutually separated conjugate pairs, and nonzero selected weights. That theorem supplies real polynomials P(j) with energy of sum_j t(j) P(j) at most minus sum_j t(j) squared for every real t. Their linear combination map T is injective: if T(t)=0 for nonzero t, its zero energy contradicts the strictly negative bound, since a nonzero real vector has positive sum of squares. Applying the same argument to differences proves injectivity, so k belongs to negativeRanks and k is at most negativeIndex by the defining supremum. When those k pairs also exhaust every active nonreal pair and the real-node sign hypothesis holds, the present upper bound with r=k gives negativeIndex=k. This is a derivation for a later transient compiled application, with no additional named equality wrapper retained here. The staged simultaneous integerization strengthens the lower witnesses to one integer family preserving negativity for every nonzero real combination; it supplies no missing coverage hypothesis.")),
                    Paragraph(Text("For repeated nodes, the present entrywise cover can overcount. An exact interpretation as a number of pairs must first aggregate weights at each identical node, retain only nonzero aggregate weights, and count distinct nonreal conjugate node pairs. Cancellations can remove an apparent pair. The preceding equality derivation applies directly to an injective, already aggregated presentation satisfying the lower theorem's hypotheses; no regrouping theorem for repeated nodes is claimed here.")),
                    Paragraph(Text("Pinned API review uses Mathlib 56a005855ea17e0b0958f73ec801ae140b0a1679 and Lean 4.35. IsAlgClosed.exists_pow_nat_eq takes the weight followed by a proof that the natural exponent is positive; its witness satisfies b squared equals the weight. Polynomial.aeval_conj takes the real polynomial and then the node, with evaluation at the conjugate on the left. LinearMap.mulLeft takes the scalar ring and then the left multiplier; Complex.imLm is real linear. Complex.re_tsum requires summability of the complex summands, supplied here by square_summable, while tsum_nonneg consumes their pointwise real-part signs. LinearMap.finrank_le_finrank_of_injective takes an injectivity proof with the map implicit, and Module.finrank_fin_fun computes the two finite real coordinate dimensions. WithTop.coe_le_coe transports the resulting natural inequality.")),
                    Paragraph(Text("The read-only actual-xi consumer with SHA256 301afbbafff8ddd3b7875dc423a2d54a779373b8effe29fb9576d289c037b7e2 applies this exact upper theorem to node, weight and the actual positive-height conjugation permutation. Its finite selector enumerates upper-half zeros strictly right of the critical line; the actual tau involution covers the left side. Real folded nodes have positive real weight by node_real_positive. The lower call uses the already compiled pinned integer-family supplier, distinct-node injectivity and separated quartet representatives. Its two owner-local helpers node_large_finite and weight_ne_zero remain private in ActualXiIntegerCriterion and need visibility changes at their original owner only during future canonical integration. No helper proof is copied here, and no actual consumer source is changed. The consumer's existing Polynomial.ofFn/toFn support and energy transport, finite and infinite ENat.card branches, and original derivative xiCoefficient identity were inspected; every consumer proof remains uncompiled.")),
                    Paragraph(Text("This is source preparation for the existing classical index reasoning of the owning theory, section 6 and editorial note n29, rather than a new mathematical existence or novelty claim. It neither supplies an off-axis zeta pair nor proves RH. The Lean draft and this Scribe have not been compiled or accepted by repository checks. Canonical integration must validate the pinned dependency and the Lean and Scribe, and the required truthful Reg registration or linked-issue exception under the repository rules."))),
                DescribeRole.Theorem))));
}
